with seed(slug, sections, assessment) as (values
  ('never-outshine-the-master', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A project lead introduces your prototype to sponsors.","Explain your contribution and credit the lead for securing the resources."],"bodyBn":["একজন প্রকল্পনেতা পৃষ্ঠপোষকদের কাছে আপনার প্রোটোটাইপ তুলে ধরছেন।","নিজের অবদান ব্যাখ্যা করুন এবং সম্পদ জোগাড়ের কৃতিত্ব নেতাকে দিন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["If quality or safety is at risk, raise the facts through the responsible channel promptly. Giving credit should never obscure who did the work."],"bodyBn":["মান বা নিরাপত্তা ঝুঁকিতে থাকলে দায়িত্বপ্রাপ্ত পথে দ্রুত তথ্য জানান। কৃতিত্ব ভাগ করতে গিয়ে কে কাজ করেছেন তা আড়াল করা উচিত নয়।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A project lead introduces your prototype to sponsors. Which response best applies the lesson responsibly?","questionBn":"একজন প্রকল্পনেতা পৃষ্ঠপোষকদের কাছে আপনার প্রোটোটাইপ তুলে ধরছেন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Explain your contribution and credit the lead for securing the resources.","Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["নিজের অবদান ব্যাখ্যা করুন এবং সম্পদ জোগাড়ের কৃতিত্ব নেতাকে দিন।","এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":0,"explanationEn":"Explain your contribution and credit the lead for securing the resources.","explanationBn":"নিজের অবদান ব্যাখ্যা করুন এবং সম্পদ জোগাড়ের কৃতিত্ব নেতাকে দিন।"}]}'::jsonb),
  ('never-trust-too-much-friends', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A close friend and a former competitor apply for the same team role.","Give both candidates the same work sample and judge them by the same rubric."],"bodyBn":["এক ঘনিষ্ঠ বন্ধু ও এক সাবেক প্রতিদ্বন্দ্বী দলের একই পদের জন্য আবেদন করেছেন।","দুজনকে একই নমুনা কাজ দিন এবং একই মানদণ্ডে মূল্যায়ন করুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["A history of friendship or rivalry can explain an expectation, but neither predicts job performance without evidence. Apply conflict-of-interest rules before you score candidates."],"bodyBn":["বন্ধুত্ব বা প্রতিদ্বন্দ্বিতা প্রত্যাশা ব্যাখ্যা করতে পারে, কিন্তু প্রমাণ ছাড়া কাজের মান বোঝায় না। নম্বর দেওয়ার আগে স্বার্থের সংঘাতের নিয়ম মানুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A close friend and a former competitor apply for the same team role. Which response best applies the lesson responsibly?","questionBn":"এক ঘনিষ্ঠ বন্ধু ও এক সাবেক প্রতিদ্বন্দ্বী দলের একই পদের জন্য আবেদন করেছেন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined.","Give both candidates the same work sample and judge them by the same rubric."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি 