  ('win-through-your-actions-never-through-argument', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["Two coworkers disagree about which support template saves more time.","Pilot both templates on comparable cases and compare the results."],"bodyBn":["কোন সহায়তা টেমপ্লেটে বেশি সময় বাঁচে তা নিয়ে দুই সহকর্মী একমত নন।","তুলনীয় ক্ষেত্রে দুই টেমপ্লেট পরীক্ষামূলকভাবে চালিয়ে ফল মিলিয়ে দেখুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Define the comparison before you see the numbers. Include error rate and accessibility alongside speed so the faster template does not disguise worse service."],"bodyBn":["ফল দেখার আগে তুলনার মানদণ্ড ঠিক করুন। গতির পাশাপাশি ভুলের হার ও প্রবেশগম্যতা ধরুন যাতে দ্রুততর টেমপ্লেট খারাপ সেবা ঢেকে না দেয়।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"Two coworkers disagree about which support template saves more time. Which response best applies the lesson responsibly?","questionBn":"কোন সহায়তা টেমপ্লেটে বেশি সময় বাঁচে তা নিয়ে দুই সহকর্মী একমত নন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Pilot both templates on comparable cases and compare the results.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","তুলনীয় ক্ষেত্রে দুই টেমপ্লেট পরীক্ষামূলকভাবে চালিয়ে ফল মিলিয়ে দেখুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":2,"explanationEn":"Pilot both templates on comparable cases and compare the results.","explanationBn":"তুলনীয় ক্ষেত্রে দুই টেমপ্লেট পরীক্ষামূলকভাবে চালিয়ে ফল মিলিয়ে দেখুন।"}]}'::jsonb),
  ('infection-avoid-the-unhappy-and-unlucky', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["Chronic venting is crowding out work in a team chat.","Move the discussion to a bounded check-in and offer practical support."],"bodyBn":["দলের চ্যাটে লাগাতার অভিযোগের কারণে কাজের আলোচনা চাপা পড়ছে।","নির্দিষ্ট সময়ের আলাদা আলোচনায় বিষয়টি তুলুন এবং বাস্তব সহায়তা দিন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["The useful boundary is about recurring behavior and its effect on the team. Distress by itself calls for empathy and appropriate support."],"bodyBn":["সীমা টানার কারণ হলো পুনরাবৃত্ত আচরণ ও দলের ওপর তার প্রভাব। কষ্টে থাকা মানুষের প্রতি সহমর্মিতা ও উপযুক্ত সহায়তা দিন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"Chronic venting is crowding out work in a team chat. Which response best applies the lesson responsibly?","questionBn":"দলের চ্যাটে লাগাতার অভিযোগের কারণে কাজের আলোচনা চাপা পড়ছে। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Move the discussion to a bounded check-in and offer practical support.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","নির্দিষ্ট সময়ের আলাদা আলোচনায় বিষয়টি তুলুন এবং বাস্তব সহায়তা দিন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":1,"explanationEn":"Move the discussion to a bounded check-in and offer practical support.","explanationBn":"নির্দিষ্ট সময়ের আলাদা আলোচনায় বিষয়টি তুলুন এবং বাস্তব সহায়তা দিন।"}]}'::jsonb),
  ('learn-to-keep-people-dependent-on-you', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["One specialist maintains a tool everyone needs.","Demonstrate the value of the specialty while documenting recovery and training a backup."],"bodyBn":["সবার প্রয়োজন এমন একটি সরঞ্জাম একজন বিশেষজ্ঞ একাই রক্ষণাবেক্ষণ করেন।","বিশেষ দক্ষতার মূল্য দেখানোর পাশাপাশি পুনরুদ্ধারের পদ্ধতি লিখুন ও বিকল্প কর্মীকে প্রশিক্ষণ দিন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Expertise creates durable influence when people choose to seek it. A single point of failure creates short-term dependence and long-term risk."],"bodyBn":["মানুষ স্বেচ্ছায় দক্ষতার সাহায্য চাইলে দীর্ঘস্থায়ী প্রভাব তৈরি হয়। একমাত্র নির্ভরতার জায়গা স্বল্পমেয়াদি নির্ভরতা ও দীর্ঘমেয়াদি ঝুঁকি তৈরি করে।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"One specialist maintains a tool everyone needs. Which response best applies the lesson responsibly?","questionBn":"সবার প্রয়োজন এমন একটি সরঞ্জাম একজন বিশেষজ্ঞ একাই রক্ষণাবেক্ষণ করেন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Demonstrate the value of the specialty while documenting recovery and training a backup.","Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["বিশেষ দক্ষতার মূল্য দেখানোর পাশাপাশি পুনরুদ্ধারের পদ্ধতি লিখুন ও বিকল্প কর্মীকে প্রশিক্ষণ দিন।","এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":0,"explanationEn":"Demonstrate the value of the specialty while documenting recovery and training a backup.","explanationBn":"বিশেষ দক্ষতার মূল্য দেখানোর পাশাপাশি পুনরুদ্ধারের পদ্ধতি লিখুন ও বিকল্প কর্মীকে প্রশিক্ষণ দিন।"}]}'::jsonb),
  ('use-selective-honesty-and-generosity', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A new vendor gives your team a generous gift before procurement.","Disclose the gift and independently evaluate the vendor under procurement rules."],"bodyBn":["ক্রয়ের সিদ্ধান্তের আগে নতুন বিক্রেতা আপনার দলকে মূল্যবান উপহার দিয়েছেন।","উপহারটির কথা জানান এবং ক্রয়বিধি মেনে বিক্রেতাকে স্বাধীনভাবে মূল্যায়ন করুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["An honest disclosure or generous gesture is evidence of that act alone. Check the broader deal, including price, conditions, and obligations."],"bodyBn":["সৎ স্বীকারোক্তি বা উদারতা শুধু সেই কাজের প্রমাণ। দাম, শর্ত ও দায়বদ্ধতাসহ পুরো চুক্তি যাচাই করুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A new vendor gives your team a generous gift before procurement. Which response best applies the lesson responsibly?","questionBn":"ক্রয়ের সিদ্ধান্তের আগে নতুন বিক্রেতা আপনার দলকে মূল্যবান উপহার দিয়েছেন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined.","Disclose the gift and independently evaluate the vendor under procurement rules."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।","উপহারটির কথা জানান এবং ক্রয়বিধি মেনে বিক্রেতাকে স্বাধীনভাবে মূল্যায়ন করুন।"],"correctOption":3,"explanationEn":"Disclose the gift and independently evaluate the vendor under procurement rules.","explanationBn":"উপহারটির কথা জানান এবং ক্রয়বিধি মেনে বিক্রেতাকে স্বাধীনভাবে মূল্যায়ন করুন।"}]}'::jsonb),
  ('when-asking-for-help-appeal-to-self-interest', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["You need another department to lend staff for a pilot.","Explain what the pilot will save their department and agree on the time commitment."],"bodyBn":["পরীক্ষামূলক উদ্যোগের জন্য অন্য বিভাগ থেকে কর্মী দরকার।","উদ্যোগটি তাদের বিভাগের কী সাশ্রয় করবে তা ব্যাখ্যা করুন এবং সময়ের সীমায় সম্মত হন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["A mutual benefit must be concrete enough for the other team to evaluate. Ask what they would count as a worthwhile return."],"bodyBn":["পারস্পরিক সুবিধা এমন নির্দিষ্ট হওয়া চাই যাতে অন্য দল তা বিচার করতে পারে। তাদের কাছে কোন ফল লাভজনক হবে জিজ্ঞাসা করুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"You need another department to lend staff for a pilot. Which response best applies the lesson responsibly?","questionBn":"পরীক্ষামূলক উদ্যোগের জন্য অন্য বিভাগ থেকে কর্মী দরকার। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined.","Explain what the pilot will save their department and agree on the time commitment."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।","উদ্যোগটি তাদের বিভাগের কী সাশ্রয় করবে তা ব্যাখ্যা করুন এবং সময়ের সীমায় সম্মত হন।"],"correctOption":3,"explanationEn":"Explain what the pilot will save their department and agree on the time commitment.","explanationBn":"উদ্যোগটি তাদের বিভাগের কী সাশ্রয় করবে তা ব্যাখ্যা করুন এবং সময়ের সীমায় সম্মত হন।"}]}'::jsonb),
  ('pose-as-a-friend-work-as-a-spy', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["You want to understand why people avoid a new service.","Invite candid feedback and state how the responses will be used."],"bodyBn":["মানুষ কেন নতুন সেবাটি এড়িয়ে যাচ্ছে তা জানতে চান।","খোলামেলা মতামত চান এবং উত্তরগুলো কীভাবে ব্যবহার হবে তা জানান।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Collect observations people agreed to share. Limit personal information and keep feedback anonymous when its disclosure could carry a cost."],"bodyBn":["মানুষ যে তথ্য ভাগ করতে সম্মত হয়েছে তা সংগ্রহ করুন। ব্যক্তিগত তথ্য সীমিত রাখুন এবং প্রকাশে ক্ষতির আশঙ্কা থাকলে মতামত নামবিহীন রাখুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"You want to understand why people avoid a new service. Which response best applies the lesson responsibly?","questionBn":"মানুষ কেন নতুন সেবাটি এড়িয়ে যাচ্ছে তা জানতে চান। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Invite candid feedback and state how the responses will be used.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","খোলামেলা মতামত চান এবং উত্তরগুলো কীভাবে ব্যবহার হবে তা জানান।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":2,"explanationEn":"Invite candid feedback and state how the responses will be used.","explanationBn":"খোলামেলা মতামত চান এবং উত্তরগুলো কীভাবে ব্যবহার হবে তা জানান।"}]}'::jsonb),
  ('crush-your-enemy-totally', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A recurring dispute returns every time a shift changes.","Fix the ambiguous handoff and assign responsibility in writing."],"bodyBn":["প্রতি পালাবদলে একই বিরোধ আবার দেখা দিচ্ছে।","দায়িত্ব হস্তান্তরের অস্পষ্টতা দূর করুন এবং দায়িত্ব লিখিতভাবে ঠিক করুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["A durable settlement removes the circumstances that recreate the conflict. Retaliation leaves the root cause in place and adds another dispute."],"bodyBn":["টেকসই সমাধান সংঘাত আবার তৈরি হওয়ার পরিস্থিতি দূর করে। প্রতিশোধ মূল কারণ রেখে নতুন বিরোধ যোগ করে।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A recurring dispute returns every time a shift changes. Which response best applies the lesson responsibly?","questionBn":"প্রতি পালাবদলে একই বিরোধ আবার দেখা দিচ্ছে। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Fix the ambiguous handoff and assign responsibility in writing.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","দায়িত্ব হস্তান্তরের অস্পষ্টতা দূর করুন এবং দায়িত্ব লিখিতভাবে ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":1,"explanationEn":"Fix the ambiguous handoff and assign responsibility in writing.","explanationBn":"দায়িত্ব হস্তান্তরের অস্পষ্টতা দূর করুন এবং দায়িত্ব লিখিতভাবে ঠিক করুন।"}]}'::jsonb),
  ('use-absence-to-increase-respect-and-honor', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A mentor is overwhelmed by ad hoc requests.","Offer reliable office hours and keep urgent escalation available."],"bodyBn":["অনিয়মিত অনুরোধের চাপে একজন পরামর্শদাতা হিমশিম খাচ্ছেন।","নিয়মিত পরামর্শের সময় ঠিক করুন এবং জরুরি যোগাযোগের পথ খোলা রাখুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Predictable availability makes a boundary workable for others. Absence that interrupts promised support erodes the respect you wanted to preserve."],"bodyBn":["কখন পাওয়া যাবে জানা থাকলে অন্যরা সীমা মেনে কাজ করতে পারেন। প্রতিশ্রুত সহায়তা বন্ধ করা অনুপস্থিতি সম্মান ক্ষয় করে।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A mentor is overwhelmed by ad hoc requests. Which response best applies the lesson responsibly?","questionBn":"অনিয়মিত অনুরোধের চাপে একজন পরামর্শদাতা হিমশিম খাচ্ছেন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Offer reliable office hours and keep urgent escalation available.","Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["নিয়মিত পরামর্শের সময় ঠিক করুন এবং জরুরি যোগাযোগের পথ খোলা রাখুন।","এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":0,"explanationEn":"Offer reliable office hours and keep urgent escalation available.","explanationBn":"নিয়মিত পরামর্শের সময় ঠিক করুন এবং জরুরি যোগাযোগের পথ খোলা রাখুন।"}]}'::jsonb),
  ('keep-others-in-suspended-terror', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A competitor anticipates every public product announcement.","Vary release formats while keeping commitments to customers predictable."],"bodyBn":["এক প্রতিদ্বন্দ্বী প্রতিটি প্রকাশ্য পণ্য ঘোষণার আগেই তা অনুমান করে ফেলেন।","প্রকাশনার ধরন বদলান, কিন্তু গ্রাহকদের দেওয়া প্রতিশ্রুতি স্থির রাখুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Keep operational obligations predictable even when tactics change. People who rely on you need stable deadlines and a way to reach you."],"bodyBn":["কৌশল বদলালেও কাজের দায়বদ্ধতা স্থির রাখুন। নির্ভরশীল মানুষের স্থির সময়সীমা ও যোগাযোগের পথ দরকার।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A competitor anticipates every public product announcement. Which response best applies the lesson responsibly?","questionBn":"এক প্রতিদ্বন্দ্বী প্রতিটি প্রকাশ্য পণ্য ঘোষণার আগেই তা অনুমান করে ফেলেন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Vary release formats while keeping commitments to customers predictable.","Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["প্রকাশনার ধরন বদলান, কিন্তু গ্রাহকদের দেওয়া প্রতিশ্রুতি স্থির রাখুন।","এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":0,"explanationEn":"Vary release formats while keeping commitments to customers predictable.","explanationBn":"প্রকাশনার ধরন বদলান, কিন্তু গ্রাহকদের দেওয়া প্রতিশ্রুতি স্থির রাখুন।"}]}'::jsonb),
  ('do-not-build-fortress-to-protect-yourself', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A remote team has stopped hearing about problems in adjacent teams.","Set up recurring cross-team check-ins to exchange early warnings."],"bodyBn":["দূর থেকে কাজ করা একটি দল পাশের দলগুলোর সমস্যা আর জানতে পারছে না।","আগাম সতর্কতা বিনিময়ের জন্য দলগুলোর মধ্যে নিয়মিত সংক্ষিপ্ত সভা চালু করুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["More contacts help only when useful information can travel both ways. Give partner teams a clear path for reporting problems."],"bodyBn":["উপকারী তথ্য দুই দিকেই চললে যোগাযোগ বাড়ানোর লাভ আছে। অন্য দলকে সমস্যা জানানোর স্পষ্ট পথ দিন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A remote team has stopped hearing about problems in adjacent teams. Which response best applies the lesson responsibly?","questionBn":"দূর থেকে কাজ করা একটি দল পাশের দলগুলোর সমস্যা আর জানতে পারছে না। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined.","Set up recurring cross-team check-ins to exchange early warnings."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।","আগাম সতর্কতা বিনিময়ের জন্য দলগুলোর মধ্যে নিয়মিত সংক্ষিপ্ত সভা চালু করুন।"],"correctOption":3,"explanationEn":"Set up recurring cross-team check-ins to exchange early warnings.","explanationBn":"আগাম সতর্কতা বিনিময়ের জন্য দলগুলোর মধ্যে নিয়মিত সংক্ষিপ্ত সভা চালু করুন।"}]}'::jsonb),
  ('know-who-youre-dealing-with', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A joke that works with close peers may land badly with a new client.","Ask about expectations and use neutral language until you know the context."],"bodyBn":["ঘনিষ্ঠ সহকর্মীদের সঙ্গে মানানসই একটি রসিকতা নতুন গ্রাহকের কাছে অস্বস্তিকর হতে পারে।","প্রত্যাশা সম্পর্কে জিজ্ঞাসা করুন এবং প্রেক্ষাপট বোঝা পর্যন্ত নিরপেক্ষ ভাষা ব্যবহার করুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Read the circumstances and the person''s expectations before using humor or criticism. Avoid treating title, age, or background as a substitute for observation."],"bodyBn":["রসিকতা বা সমালোচনার আগে পরিস্থিতি ও ব্যক্তির প্রত্যাশা বুঝুন। পদ, বয়স বা পরিচয়কে পর্যবেক্ষণের বিকল্প ভাববেন না।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A joke that works with close peers may land badly with a new client. Which response best applies the lesson responsibly?","questionBn":"ঘনিষ্ঠ সহকর্মীদের সঙ্গে মানানসই একটি রসিকতা নতুন গ্রাহকের কাছে অস্বস্তিকর হতে পারে। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Ask about expectations and use neutral language until you know the context.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","প্রত্যাশা সম্পর্কে জিজ্ঞাসা করুন এবং প্রেক্ষাপট বোঝা পর্যন্ত নিরপেক্ষ ভাষা ব্যবহার করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":2,"explanationEn":"Ask about expectations and use neutral language until you know the context.","explanationBn":"প্রত্যাশা সম্পর্কে জিজ্ঞাসা করুন এবং প্রেক্ষাপট বোঝা পর্যন্ত নিরপেক্ষ ভাষা ব্যবহার করুন।"}]}'::jsonb),
  ('do-not-commit-to-anyone', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["Two internal groups ask for exclusive support before a proposal is evaluated.","Share the decision criteria and withhold any exclusive commitment until review."],"bodyBn":["প্রস্তাব মূল্যায়নের আগেই দুটি অভ্যন্তরীণ দল একচেটিয়া সমর্থন চায়।","সিদ্ধান্তের মানদণ্ড জানান এবং পর্যালোচনা পর্যন্ত একচেটিয়া প্রতিশ্রুতি স্থগিত রাখুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Preserve independent judgment while meeting commitments already made. Tell people when and how a decision will actually be taken."],"bodyBn":["আগে দেওয়া প্রতিশ্রুতি রেখে স্বাধীন বিচার বজায় রাখুন। সিদ্ধান্ত কখন ও কীভাবে হবে তা সংশ্লিষ্টদের জানান।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"Two internal groups ask for exclusive support before a proposal is evaluated. Which response best applies the lesson responsibly?","questionBn":"প্রস্তাব মূল্যায়নের আগেই দুটি অভ্যন্তরীণ দল একচেটিয়া সমর্থন চায়। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Share the decision criteria and withhold any exclusive commitment until review.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","সিদ্ধান্তের মানদণ্ড জানান এবং পর্যালোচনা পর্যন্ত একচেটিয়া প্রতিশ্রুতি স্থগিত রাখুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":1,"explanationEn":"Share the decision criteria and withhold any exclusive commitment until review.","explanationBn":"সিদ্ধান্তের মানদণ্ড জানান এবং পর্যালোচনা পর্যন্ত একচেটিয়া প্রতিশ্রুতি স্থগিত রাখুন।"}]}'::jsonb),
  ('play-a-sucker-to-catch-a-sucker', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A supplier speaks in jargon and assumes you will accept its estimate.","Ask plain questions that surface the assumptions and compare independent estimates."],"bodyBn":["এক সরবরাহকারী দুর্বোধ্য পরিভাষা ব্যবহার করে ধরে নিয়েছেন যে আপনি তাঁর হিসাব মেনে নেবেন।","সহজ প্রশ্নে হিসাবের অনুমানগুলো বের করুন এবং স্বাধীন হিসাবের সঙ্গে তুলনা করুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Basic questions test jargon and hidden assumptions. They are most useful when you can also check the answers against independent evidence."],"bodyBn":["সহজ প্রশ্ন দুর্বোধ্য পরিভাষা ও গোপন অনুমান যাচাই করে। উত্তর স্বাধীন প্রমাণের সঙ্গে মিলিয়ে দেখতে পারলে এগুলো আরও কার্যকর।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A supplier speaks in jargon and assumes you will accept its estimate. Which response best applies the lesson responsibly?","questionBn":"এক সরবরাহকারী দুর্বোধ্য পরিভাষা ব্যবহার করে ধরে নিয়েছেন যে আপনি তাঁর হিসাব মেনে নেবেন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Ask plain questions that surface the assumptions and compare independent estimates.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","সহজ প্রশ্নে হিসাবের অনুমানগুলো বের করুন এবং স্বাধীন হিসাবের সঙ্গে তুলনা করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":1,"explanationEn":"Ask plain questions that surface the assumptions and compare independent estimates.","explanationBn":"সহজ প্রশ্নে হিসাবের অনুমানগুলো বের করুন এবং স্বাধীন হিসাবের সঙ্গে তুলনা করুন।"}]}'::jsonb),
  ('use-surrender-tactic-transform-weakness-into-power', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A small team cannot win an immediate dispute over meeting space.","Agree on a temporary schedule and reopen the question with usage data."],"bodyBn":["সভাকক্ষ নিয়ে তাৎক্ষণিক বিরোধে ছোট একটি দলের জেতার সুযোগ নেই।","সাময়িক সময়সূচিতে সম্মত হন এবং ব্যবহারের তথ্য নিয়ে বিষয়টি আবার তুলুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Accept only a reversible compromise whose review date is real. A vague promise to revisit can turn a temporary concession into a permanent one."],"bodyBn":["যে সাময়িক সমঝোতা ফিরিয়ে নেওয়া যায় এবং যার পর্যালোচনার তারিখ ঠিক আছে সেটিই নিন। অস্পষ্ট আশ্বাসে সাময়িক ছাড় স্থায়ী হতে পারে।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A small team cannot win an immediate dispute over meeting space. Which response best applies the lesson responsibly?","questionBn":"সভাকক্ষ নিয়ে তাৎক্ষণিক বিরোধে ছোট একটি দলের জেতার সুযোগ নেই। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Agree on a temporary schedule and reopen the question with usage data.","Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["সাময়িক সময়সূচিতে সম্মত হন এবং ব্যবহারের তথ্য নিয়ে বিষয়টি আবার তুলুন।","এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":0,"explanationEn":"Agree on a temporary schedule and reopen the question with usage data.","explanationBn":"সাময়িক সময়সূচিতে সম্মত হন এবং ব্যবহারের তথ্য নিয়ে বিষয়টি আবার তুলুন।"}]}'::jsonb),
  ('concentrate-your-forces', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A pilot has funding for one meaningful improvement.","Identify the biggest bottleneck and put the pilot budget toward it."],"bodyBn":["পরীক্ষামূলক উদ্যোগে একটি অর্থপূর্ণ উন্নতির জন্য অর্থ আছে।","সবচেয়ে বড় বাধা চিহ্নিত করে তাতেই পরীক্ষার বাজেট দিন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Concentrate effort where there is evidence of a bottleneck. Keep essential maintenance funded even when a pilot has a single focus."],"bodyBn":["বাধার প্রমাণ যে জায়গায় আছে সেখানে প্রচেষ্টা দিন। পরীক্ষার লক্ষ্য একটি হলেও প্রয়োজনীয় রক্ষণাবেক্ষণের অর্থ রাখুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A pilot has funding for one meaningful improvement. Which response best applies the lesson responsibly?","questionBn":"পরীক্ষামূলক উদ্যোগে একটি অর্থপূর্ণ উন্নতির জন্য অর্থ আছে। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined.","Identify the biggest bottleneck and put the pilot budget toward it."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।","সবচেয়ে বড় বাধা চিহ্নিত করে তাতেই পরীক্ষার বাজেট দিন।"],"correctOption":3,"explanationEn":"Identify the biggest bottleneck and put the pilot budget toward it.","explanationBn":"সবচেয়ে বড় বাধা চিহ্নিত করে তাতেই পরীক্ষার বাজেট দিন।"}]}'::jsonb),
  ('play-the-perfect-courtier', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["You need to raise an executive decision that hurt another team.","Bring specific evidence to a private conversation and propose a repair."],"bodyBn":["ঊর্ধ্বতনের একটি সিদ্ধান্ত অন্য দলের ক্ষতি করেছে এবং বিষয়টি তুলতে হবে।","নির্দিষ্ট প্রমাণ নিয়ে একান্তে আলোচনা করুন এবং সমাধান প্রস্তাব করুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Tact improves the chance that evidence is heard. Use formal reporting in situations that require accountability or independent review."],"bodyBn":["কৌশলী উপস্থাপনা প্রমাণ শোনার সম্ভাবনা বাড়ায়। জবাবদিহি বা স্বাধীন পর্যালোচনা দরকার হলে আনুষ্ঠানিকভাবে জানান।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"You need to raise an executive decision that hurt another team. Which response best applies the lesson responsibly?","questionBn":"ঊর্ধ্বতনের একটি সিদ্ধান্ত অন্য দলের ক্ষতি করেছে এবং বিষয়টি তুলতে হবে। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Bring specific evidence to a private conversation and propose a repair.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","নির্দিষ্ট প্রমাণ নিয়ে একান্তে আলোচনা করুন এবং সমাধান প্রস্তাব করুন।","অন্য কারও প্রতিক্র