  ('re-create-yourself', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["You move from individual contributor to team manager.","Explain your new responsibilities and demonstrate them through delegation and coaching."],"bodyBn":["আপনি স্বতন্ত্র কর্মীর ভূমিকা থেকে দল পরিচালনায় এসেছেন।","নতুন দায়িত্ব ব্যাখ্যা করুন এবং কাজ ভাগ ও দিকনির্দেশনার মাধ্যমে তা দেখান।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["A new role becomes credible through repeated behavior. Communicate which responsibilities changed and who now owns your former work."],"bodyBn":["পুনরাবৃত্ত আচরণে নতুন ভূমিকা বিশ্বাসযোগ্য হয়। কোন দায়িত্ব বদলেছে এবং আগের কাজ এখন কার তা জানান।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"You move from individual contributor to team manager. Which response best applies the lesson responsibly?","questionBn":"আপনি স্বতন্ত্র কর্মীর ভূমিকা থেকে দল পরিচালনায় এসেছেন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Explain your new responsibilities and demonstrate them through delegation and coaching.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","নতুন দায়িত্ব ব্যাখ্যা করুন এবং কাজ ভাগ ও দিকনির্দেশনার মাধ্যমে তা দেখান।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":2,"explanationEn":"Explain your new responsibilities and demonstrate them through delegation and coaching.","explanationBn":"নতুন দায়িত্ব ব্যাখ্যা করুন এবং কাজ ভাগ ও দিকনির্দেশনার মাধ্যমে তা দেখান।"}]}'::jsonb),
  ('keep-your-hands-clean', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A manager asks you to send an undocumented exception to policy.","Record who approved the exception, why it exists, and when it expires."],"bodyBn":["একজন ব্যবস্থাপক নীতির একটি অলিখিত ব্যতিক্রম কার্যকর করতে বলেছেন।","কে ব্যতিক্রম অনুমোদন করেছেন, কেন করেছেন ও কখন মেয়াদ শেষ হবে তা নথিভুক্ত করুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["A reliable record includes your own part in a decision. Delegating a task does not transfer responsibility for approving it."],"bodyBn":["নির্ভরযোগ্য নথিতে সিদ্ধান্তে আপনার ভূমিকাও থাকে। কাজ ভাগ করলেই অনুমোদনের দায় অন্যের কাছে যায় না।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A manager asks you to send an undocumented exception to policy. Which response best applies the lesson responsibly?","questionBn":"একজন ব্যবস্থাপক নীতির একটি অলিখিত ব্যতিক্রম কার্যকর করতে বলেছেন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Record who approved the exception, why it exists, and when it expires.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","কে ব্যতিক্রম অনুমোদন করেছেন, কেন করেছেন ও কখন মেয়াদ শেষ হবে তা নথিভুক্ত করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":1,"explanationEn":"Record who approved the exception, why it exists, and when it expires.","explanationBn":"কে ব্যতিক্রম অনুমোদন করেছেন, কেন করেছেন ও কখন মেয়াদ শেষ হবে তা নথিভুক্ত করুন।"}]}'::jsonb),
  ('play-on-peoples-need-to-believe', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A charismatic group leader discourages anyone from questioning promises.","Ask for independent evidence and make room for dissent and voluntary exit."],"bodyBn":["এক আকর্ষণীয় দলনেতা তাঁর প্রতিশ্রুতি নিয়ে প্রশ্ন করতে সবাইকে নিরুৎসাহিত করেন।","স্বাধীন প্রমাণ চান এবং ভিন্নমত ও স্বেচ্ছায় সরে যাওয়ার সুযোগ রাখুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Belonging can motivate cooperation, but demands for uncritical loyalty undermine judgment. Look for transparent claims, safe disagreement, and accountability."],"bodyBn":["অন্তর্ভুক্তির অনুভূতি সহযোগিতা বাড়ায়, কিন্তু প্রশ্নহীন আনুগত্য বিচারশক্তি ক্ষয় করে। স্বচ্ছ দাবি, নিরাপদ ভিন্নমত ও জবাবদিহি দেখুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A charismatic group leader discourages anyone from questioning promises. Which response best applies the lesson responsibly?","questionBn":"এক আকর্ষণীয় দলনেতা তাঁর প্রতিশ্রুতি নিয়ে প্রশ্ন করতে সবাইকে নিরুৎসাহিত করেন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Ask for independent evidence and make room for dissent and voluntary exit.","Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["স্বাধীন প্রমাণ চান এবং ভিন্নমত ও স্বেচ্ছায় সরে যাওয়ার সুযোগ রাখুন।","এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":0,"explanationEn":"Ask for independent evidence and make room for dissent and voluntary exit.","explanationBn":"স্বাধীন প্রমাণ চান এবং ভিন্নমত ও স্বেচ্ছায় সরে যাওয়ার সুযোগ রাখুন।"}]}'::jsonb),
  ('enter-action-with-boldness', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A reversible experiment has been delayed for weeks by indecision.","Set a launch date, success measure, and rollback point for a limited trial."],"bodyBn":["সহজে ফিরিয়ে নেওয়া যায় এমন একটি পরীক্ষা সিদ্ধান্তহীনতায় কয়েক সপ্তাহ দেরি হয়েছে।","সীমিত পরীক্ষার শুরুর তারিখ, সফলতার মাপকাঠি ও ফিরে যাওয়ার শর্ত ঠিক করুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Move quickly when the decision is reversible and the risk bounded. Decisions exposing others to permanent harm need stronger review."],"bodyBn":["সিদ্ধান্ত ফিরিয়ে নেওয়া গেলে ও ঝুঁকি সীমিত থাকলে দ্রুত এগোন। অন্যদের স্থায়ী ক্ষতির ঝুঁকি থাকলে কঠোর পর্যালোচনা দরকার।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A reversible experiment has been delayed for weeks by indecision. Which response best applies the lesson responsibly?","questionBn":"সহজে ফিরিয়ে নেওয়া যায় এমন একটি পরীক্ষা সিদ্ধান্তহীনতায় কয়েক সপ্তাহ দেরি হয়েছে। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined.","Set a launch date, success measure, and rollback point for a limited trial."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।","সীমিত পরীক্ষার শুরুর তারিখ, সফলতার মাপকাঠি ও ফিরে যাওয়ার শর্ত ঠিক করুন।"],"correctOption":3,"explanationEn":"Set a launch date, success measure, and rollback point for a limited trial.","explanationBn":"সীমিত পরীক্ষার শুরুর তারিখ, সফলতার মাপকাঠি ও ফিরে যাওয়ার শর্ত ঠিক করুন।"}]}'::jsonb),
  ('plan-all-the-way-to-the-end', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A team plans a migration but has only scheduled the launch.","Plan validation, customer communication, and recovery through the final handoff."],"bodyBn":["একটি দল সিস্টেম স্থানান্তরের পরিকল্পনায় কেবল চালুর সময় ঠিক করেছে।","শেষ দায়িত্ব হস্তান্তর পর্যন্ত যাচাই, গ্রাহককে জানানো ও পুনরুদ্ধারের পরিকল্পনা করুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["A launch is only one point in the work. Set responsibilities and evidence requirements for delivery, maintenance, and recovery before committing."],"bodyBn":["উদ্বোধন কাজের একটি মাত্র ধাপ। প্রতিশ্রুতির আগে সরবরাহ, রক্ষণাবেক্ষণ ও পুনরুদ্ধারের দায়িত্ব এবং প্রমাণের শর্ত ঠিক করুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A team plans a migration but has only scheduled the launch. Which response best applies the lesson responsibly?","questionBn":"একটি দল সিস্টেম স্থানান্তরের পরিকল্পনায় কেবল চালুর সময় ঠিক করেছে। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined.","Plan validation, customer communication, and recovery through the final handoff."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।","শেষ দায়িত্ব হস্তান্তর পর্যন্ত যাচাই, গ্রাহককে জানানো ও পুনরুদ্ধারের পরিকল্পনা করুন।"],"correctOption":3,"explanationEn":"Plan validation, customer communication, and recovery through the final handoff.","explanationBn":"শেষ দায়িত্ব হস্তান্তর পর্যন্ত যাচাই, গ্রাহককে জানানো ও পুনরুদ্ধারের পরিকল্পনা করুন।"}]}'::jsonb),
  ('make-your-accomplishments-seem-effortless', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["Your demonstration is polished because several teammates rehearsed for days.","Keep the live demonstration concise and document and credit the preparation afterward."],"bodyBn":["কয়েকজন সহকর্মী কয়েক দিন অনুশীলন করায় আপনার প্রদর্শনী সাবলীল হয়েছে।","সরাসরি প্রদর্শনী সংক্ষিপ্ত রাখুন এবং পরে প্রস্তুতির কাজ নথিভুক্ত করে কৃতিত্ব দিন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["A fluent presentation reduces friction for the audience. Keep enough of the preparation visible that others can reproduce the result."],"bodyBn":["সাবলীল উপস্থাপনা দর্শকের বোঝা সহজ করে। অন্যরা যেন ফল পুনরায় তৈরি করতে পারেন, সে জন্য যথেষ্ট প্রস্তুতি দৃশ্যমান রাখুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"Your demonstration is polished because several teammates rehearsed for days. Which response best applies the lesson responsibly?","questionBn":"কয়েকজন সহকর্মী কয়েক দিন অনুশীলন করায় আপনার প্রদর্শনী সাবলীল হয়েছে। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Keep the live demonstration concise and document and credit the preparation afterward.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","সরাসরি প্রদর্শনী সংক্ষিপ্ত রাখুন এবং পরে প্রস্তুতির কাজ নথিভুক্ত করে কৃতিত্ব দিন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":2,"explanationEn":"Keep the live demonstration concise and document and credit the preparation afterward.","explanationBn":"সরাসরি প্রদর্শনী সংক্ষিপ্ত রাখুন এবং পরে প্রস্তুতির কাজ নথিভুক্ত করে কৃতিত্ব দিন।"}]}'::jsonb),
  ('control-the-options-get-others-to-play-with-the-cards-you-deal', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["Residents must choose between plausible service schedules.","Present the genuine options with equal detail and explain how residents can propose another."],"bodyBn":["বাসিন্দাদের কয়েকটি বাস্তবসম্মত সেবার সময়সূচি থেকে বেছে নিতে হবে।","বাস্তব বিকল্পগুলো সমান বিস্তারিতভাবে জানান এবং নতুন বিকল্প প্রস্তাবের পদ্ধতি বলুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Choice structure can clarify trade-offs or quietly constrain them. Disclose who chose the options and which alternatives were dropped."],"bodyBn":["বিকল্প সাজানো সুবিধা-অসুবিধা স্পষ্ট করতে বা গোপনে সীমিত করতে পারে। কে বিকল্প বেছেছেন এবং কোনগুলো বাদ পড়েছে জানান।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"Residents must choose between plausible service schedules. Which response best applies the lesson responsibly?","questionBn":"বাসিন্দাদের কয়েকটি বাস্তবসম্মত সেবার সময়সূচি থেকে বেছে নিতে হবে। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Present the genuine options with equal detail and explain how residents can propose another.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","বাস্তব বিকল্পগুলো সমান বিস্তারিতভাবে জানান এবং নতুন বিকল্প প্রস্তাবের পদ্ধতি বলুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":1,"explanationEn":"Present the genuine options with equal detail and explain how residents can propose another.","explanationBn":"বাস্তব বিকল্পগুলো সমান বিস্তারিতভাবে জানান এবং নতুন বিকল্প প্রস্তাবের পদ্ধতি বলুন।"}]}'::jsonb),
  ('play-to-peoples-fantasies', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A team wants to promise an unrealistically fast transformation.","Describe the desired future, the first measurable milestone, and the known constraints."],"bodyBn":["একটি দল অবাস্তব দ্রুত পরিবর্তনের প্রতিশ্রুতি দিতে চায়।","কাঙ্ক্ষিত ভবিষ্যৎ, প্রথম পরিমাপযোগ্য লক্ষ্য ও জানা সীমাবদ্ধতাগুলো জানান।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["An appealing picture can help people understand a goal. State uncertainty and invite people to verify progress against the milestones."],"bodyBn":["আকর্ষণীয় চিত্র লক্ষ্য বুঝতে সাহায্য করে। অনিশ্চয়তা জানান এবং লক্ষ্যচিহ্ন ধরে অগ্রগতি যাচাইয়ের সুযোগ দিন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A team wants to promise an unrealistically fast transformation. Which response best applies the lesson responsibly?","questionBn":"একটি দল অবাস্তব দ্রুত পরিবর্তনের প্রতিশ্রুতি দিতে চায়। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Describe the desired future, the first measurable milestone, and the known constraints.","Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["কাঙ্ক্ষিত ভবিষ্যৎ, প্রথম পরিমাপযোগ্য লক্ষ্য ও জানা সীমাবদ্ধতাগুলো জানান।","এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":0,"explanationEn":"Describe the desired future, the first measurable milestone, and the known constraints.","explanationBn":"কাঙ্ক্ষিত ভবিষ্যৎ, প্রথম পরিমাপযোগ্য লক্ষ্য ও জানা সীমাবদ্ধতাগুলো জানান।"}]}'::jsonb),
  ('discover-each-mans-thumbscrew', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["An employee is worried a proposed process will make their work invisible.","Ask what recognition they need and design feedback that makes contributions visible."],"bodyBn":["এক কর্মীর আশঙ্কা প্রস্তাবিত প্রক্রিয়ায় তাঁর কাজের দৃশ্যমানতা কমবে।","কী ধরনের স্বীকৃতি দরকার জিজ্ঞাসা করুন এবং অবদান দৃশ্যমান করে এমন প্রতিক্রিয়ার ব্যবস্থা করুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Understanding someone''s concern helps you negotiate a workable agreement. Using private vulnerabilities as leverage will often destroy the trust the agreement needs."],"bodyBn":["কারও উদ্বেগ বুঝলে কার্যকর সমঝোতা করা সহজ হয়। ব্যক্তিগত দুর্বলতা চাপ হিসেবে ব্যবহার করলে সমঝোতার জন্য দরকারি আস্থা নষ্ট হতে পারে।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"An employee is worried a proposed process will make their work invisible. Which response best applies the lesson responsibly?","questionBn":"এক কর্মীর আশঙ্কা প্রস্তাবিত প্রক্রিয়ায় তাঁর কাজের দৃশ্যমানতা কমবে। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Ask what recognition they need and design feedback that makes contributions visible.","Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["কী ধরনের স্বীকৃতি দরকার জিজ্ঞাসা করুন এবং অবদান দৃশ্যমান করে এমন প্রতিক্রিয়ার ব্যবস্থা করুন।","এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":0,"explanationEn":"Ask what recognition they need and design feedback that makes contributions visible.","explanationBn":"কী ধরনের স্বীকৃতি দরকার জিজ্ঞাসা করুন এবং অবদান দৃশ্যমান করে এমন প্রতিক্রিয়ার ব্যবস্থা করুন।"}]}'::jsonb),
  ('be-royal-in-your-own-fashion', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["You are asked to lead a meeting with more senior colleagues.","Set a clear agenda, invite contributions, and enforce the agreed time limits calmly."],"bodyBn":["ঊর্ধ্বতন সহকর্মীদের একটি সভা পরিচালনার দায়িত্ব পেয়েছেন।","স্পষ্ট আলোচ্যসূচি দিন, মতামত আহ্বান করুন এবং সম্মত সময়সীমা শান্তভাবে মানান।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Calm authority comes from owning a decision process. Make space for relevant objections, especially from people with lower status."],"bodyBn":["শান্ত কর্তৃত্ব আসে সিদ্ধান্তের প্রক্রিয়ার দায় নেওয়া থেকে। প্রাসঙ্গিক আপত্তির সুযোগ রাখুন, বিশেষ করে কম ক্ষমতাসম্পন্ন মানুষের জন্য।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"You are asked to lead a meeting with more senior colleagues. Which response best applies the lesson responsibly?","questionBn":"ঊর্ধ্বতন সহকর্মীদের একটি সভা পরিচালনার দায়িত্ব পেয়েছেন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined.","Set a clear agenda, invite contributions, and enforce the agreed time limits calmly."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।","স্পষ্ট আলোচ্যসূচি দিন, মতামত আহ্বান করুন এবং সম্মত সময়সীমা শান্তভাবে মানান।"],"correctOption":3,"explanationEn":"Set a clear agenda, invite contributions, and enforce the agreed time limits calmly.","explanationBn":"স্পষ্ট আলোচ্যসূচি দিন, মতামত আহ্বান করুন এবং সম্মত সময়সীমা শান্তভাবে মানান।"}]}'::jsonb),
  ('master-the-art-of-timing', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A major proposal is ready while your reviewers are handling an outage.","Check the deadline and schedule the review when they can give it full attention."],"bodyBn":["বড় একটি প্রস্তাব প্রস্তুত, কিন্তু পর্যালোচকেরা সেবা বিভ্রাট সামলাচ্ছেন।","শেষ সময় যাচাই করে পর্যালোচনার সময় এমনভাবে ঠিক করুন যাতে তাঁরা মনোযোগ দিতে পারেন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Timing involves both opportunity and cost of delay. Set a review date rather than indefinitely waiting for a perfect moment."],"bodyBn":["সময় বাছাইয়ে সুযোগ ও দেরির ব্যয় দুটোই আছে। আদর্শ মুহূর্তের জন্য অনির্দিষ্ট অপেক্ষা না করে পর্যালোচনার তারিখ ঠিক করুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A major proposal is ready while your reviewers are handling an outage. Which response best applies the lesson responsibly?","questionBn":"বড় একটি প্রস্তাব প্রস্তুত, কিন্তু পর্যালোচকেরা সেবা বিভ্রাট সামলাচ্ছেন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Check the deadline and schedule the review when they can give it full attention.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","শেষ সময় যাচাই করে পর্যালোচনার সময় এমনভাবে ঠিক করুন যাতে তাঁরা মনোযোগ দিতে পারেন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":2,"explanationEn":"Check the deadline and schedule the review when they can give it full attention.","explanationBn":"শেষ সময় যাচাই করে পর্যালোচনার সময় এমনভাবে ঠিক করুন যাতে তাঁরা মনোযোগ দিতে পারেন।"}]}'::jsonb),
  ('disdain-things-you-cannot-have', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A rejected pitch is consuming time needed for a better opportunity.","Record useful feedback once and move your effort to the viable opportunity."],"bodyBn":["প্রত্যাখ্যাত প্রস্তাব একটি ভালো সুযোগের জন্য দরকারি সময় নিয়ে নিচ্ছে।","কাজের মতামত একবার লিখে রাখুন এবং বাস্তবসম্মত সুযোগে সময় দিন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Stop investing attention after the answer is settled, but keep lessons that improve the next attempt. Persistent problems still need a responsible escalation path."],"bodyBn":["সিদ্ধান্ত চূড়ান্ত হলে সময় ব্যয় থামান, তবে পরের চেষ্টা উন্নত করে এমন শিক্ষা রাখুন। চলমান সমস্যার জন্য দায়িত্বপূর্ণভাবে বিষয় তোলার পথ দরকার।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A rejected pitch is consuming time needed for a better opportunity. Which response best applies the lesson responsibly?","questionBn":"প্রত্যাখ্যাত প্রস্তাব একটি ভালো সুযোগের জন্য দরকারি সময় নিয়ে নিচ্ছে। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Record useful feedback once and move your effort to the viable opportunity.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","কাজের মতামত একবার লিখে রাখুন এবং বাস্তবসম্মত সুযোগে সময় দিন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":1,"explanationEn":"Record useful feedback once and move your effort to the viable opportunity.","explanationBn":"কাজের মতামত একবার লিখে রাখুন এবং বাস্তবসম্মত সুযোগে সময় দিন।"}]}'::jsonb),
  ('create-compelling-spectacles', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A long report makes a safety trend difficult to see.","Use a clearly labeled chart with the underlying values available for inspection."],"bodyBn":["দীর্ঘ প্রতিবেদনে নিরাপত্তাজনিত একটি ধারা বোঝা কঠিন।","সহজ লেবেলসহ চার্ট ব্যবহার করুন এবং যাচাইয়ের জন্য মূল মানগুলো দেখার সুযোগ দিন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["A memorable visual should make the relevant evidence easier to inspect. Label scale, missing data, and uncertainty when they affect interpretation."],"bodyBn":["স্মরণীয় দৃশ্য প্রাসঙ্গিক প্রমাণ যাচাই সহজ করবে। ব্যাখ্যায় প্রভাব ফেললে স্কেল, অনুপস্থিত তথ্য ও অনিশ্চয়তা চিহ্নিত করুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A long report makes a safety trend difficult to see. Which response best applies the lesson responsibly?","questionBn":"দীর্ঘ প্রতিবেদনে নিরাপত্তাজনিত একটি ধারা বোঝা কঠিন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Use a clearly labeled chart with the underlying values available for inspection.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","সহজ লেবেলসহ চার্ট ব্যবহার করুন এবং যাচাইয়ের জন্য মূল মানগুলো দেখার সুযোগ দিন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":1,"explanationEn":"Use a clearly labeled chart with the underlying values available for inspection.","explanationBn":"সহজ লেবেলসহ চার্ট ব্যবহার করুন এবং যাচাইয়ের জন্য মূল মানগুলো দেখার সুযোগ দিন।"}]}'::jsonb),
  ('think-as-you-like-but-behave-like-others', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["You are new to a team with unfamiliar communication conventions.","Use the team''s meeting conventions while raising substantive questions respectfully."],"bodyBn":["অপরিচিত যোগাযোগরীতি আছে এমন একটি দলে আপনি নতুন।","দলের সভার রীতি মেনে চলুন এবং গুরুত্বপূর্ণ প্রশ্ন শ্রদ্ধার সঙ্গে তুলুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Adapting to ordinary norms can improve cooperation without changing your judgment. Challenge a norm openly if it violates policy or excludes people."],"bodyBn":["সাধারণ রীতির সঙ্গে মানিয়ে বিচার অক্ষুণ্ণ রেখেও সহযোগিতা বাড়ানো যায়। নিয়ম ভাঙে বা মানুষকে বাদ দেয় এমন রীতি প্রকাশ্যে প্রশ্ন করুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"You are new to a team with unfamiliar communication conventions. Which response best applies the lesson responsibly?","questionBn":"অপরিচিত যোগাযোগরীতি আছে এমন একটি দলে আপনি নতুন। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Use the team''s meeting conventions while raising substantive questions respectfully.","Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["দলের সভার রীতি মেনে চলুন এবং গুরুত্বপূর্ণ প্রশ্ন শ্রদ্ধার সঙ্গে তুলুন।","এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।"],"correctOption":0,"explanationEn":"Use the team''s meeting conventions while raising substantive questions respectfully.","explanationBn":"দলের সভার রীতি মেনে চলুন এবং গুরুত্বপূর্ণ প্রশ্ন শ্রদ্ধার সঙ্গে তুলুন।"}]}'::jsonb),
  ('stir-up-waters-to-catch-fish', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A negotiation becomes heated after an accusation.","Pause the discussion and return to verifiable claims after a short break."],"bodyBn":["অভিযোগ ওঠার পর একটি আলোচনা উত্তপ্ত হয়ে উঠেছে।","আলোচনা থামিয়ে ছোট বিরতির পর যাচাই করা যায় এমন বক্তব্যে ফিরুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Agitation can reveal how a discussion is being steered, but it also lowers judgment. Slow the exchange and distinguish evidence from provocation."],"bodyBn":["উত্তেজনা আলোচনা কীভাবে চালিত হচ্ছে তা দেখায়, কিন্তু বিচার দুর্বলও করে। গতি কমিয়ে উসকানি থেকে প্রমাণ আলাদা করুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A negotiation becomes heated after an accusation. Which response best applies the lesson responsibly?","questionBn":"অভিযোগ ওঠার পর একটি আলোচনা উত্তপ্ত হয়ে উঠেছে। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Wait for someone else to respond and leave the next step undefined.","Pause the discussion and return to verifiable claims after a short break."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","অন্য কারও প্রতিক্রিয়ার অপেক্ষা করুন এবং পরবর্তী ধাপ অনির্ধারিত রাখুন।","আলোচনা থামিয়ে ছোট বিরতির পর যাচাই করা যায় এমন বক্তব্যে ফিরুন।"],"correctOption":3,"explanationEn":"Pause the discussion and return to verifiable claims after a short break.","explanationBn":"আলোচনা থামিয়ে ছোট বিরতির পর যাচাই করা যায় এমন বক্তব্যে ফিরুন।"}]}'::jsonb),
  ('despise-the-free-lunch', '[{"headingEn":"Worked example","headingBn":"উদাহরণ ও প্রয়োগ","bodyEn":["A vendor offers free equipment in exchange for unspecified future access.","Request written terms and calculate the cost of the obligations before deciding."],"bodyBn":["ভবিষ্যতে অস্পষ্ট প্রবেশাধিকারের বিনিময়ে বিক্রেতা বিনামূল্যে সরঞ্জাম দিতে চান।","সিদ্ধান্তের আগে লিখিত শর্ত চান এবং দায়বদ্ধতার ব্যয় হিসাব করুন।"]},{"headingEn":"When to adjust","headingBn":"কখন পদ্ধতি বদলাবেন","bodyEn":["Calculate the cost across the whole relationship. Check exclusivity, future dependence, and data access alongside the headline price."],"bodyBn":["পুরো সম্পর্কের ব্যয় হিসাব করুন। ঘোষিত দামের পাশাপাশি একচেটিয়া শর্ত, ভবিষ্যৎ নির্ভরতা ও তথ্যের প্রবেশাধিকার যাচাই করুন।"]},{"headingEn":"Reflection","headingBn":"অনুশীলন","bodyEn":["Identify who has decision-making power in this situation. What would tell you that the response helped, and what would lead you to change course?"],"bodyBn":["এই পরিস্থিতিতে সিদ্ধান্ত নেওয়ার ক্ষমতা কার আছে তা চিহ্নিত করুন। কী দেখে বুঝবেন পদক্ষেপটি কাজে লেগেছে, আর কী দেখে পদ্ধতি বদলাবেন?"]}]'::jsonb, '{"isPublished":true,"passPercentage":100,"questions":[{"id":"practical-response","questionEn":"A vendor offers free equipment in exchange for unspecified future access. Which response best applies the lesson responsibly?","questionBn":"ভবিষ্যতে অস্পষ্ট প্রবেশাধিকারের বিনিময়ে বিক্রেতা বিনামূল্যে সরঞ্জাম দিতে চান। কোন প্রতিক্রিয়াটি দায়িত্বশীলভাবে শিক্ষাটি প্রয়োগ করে?","optionsEn":["Make a public commitment immediately and work out the details later.","Follow the usual process without checking whether it fits this situation.","Request written terms and calculate the cost of the obligations before deciding.","Wait for someone else to respond and leave the next step undefined."],"optionsBn":["এখনই প্রকাশ্যে প্রতিশ্রুতি দিন এবং পরে বিস্তারিত ঠিক করুন।","এই পরিস্থিতির সঙ্গে মানানসই কি না যাচাই না করে প্রচলিত পদ্ধতি অনুসরণ করুন।","সিদ্ধান্তের আগে লিখিত শর্ত চান এ